packagegui.custom_php_after_head_command:
$pkg_version = dnscrypt_proxy_get_pkg_version();
$binary_version = dnscrypt_proxy_get_version();
echo "<script>document.addEventListener('DOMContentLoaded', function() { ";
echo "var pkgEl = document.getElementById('pkg-version'); if (pkgEl) pkgEl.textContent = " . json_encode($pkg_version) . "; ";
echo "var binEl = document.getElementById('dnscrypt-version'); if (binEl) binEl.textContent = " . json_encode($binary_version) . "; ";
echo "});</script>";
